const fs = require('fs');
const path = require('path');

// Read .env.test file
const envPath = path.join(__dirname, '.env.test');
let envContent = {};

try {
  const data = fs.readFileSync(envPath, 'utf8');
  const lines = data.split('\n');

  lines.forEach(line => {
    line = line.trim();
    if (line && !line.startsWith('#')) {
      const [key, value] = line.split('=');
      if (key && value) {
        envContent[key] = value;
      }
    }
  });

  console.log('Read secrets:', JSON.stringify(envContent, null, 2));
} catch (err) {
  console.error('Error reading .env.test:', err);
  process.exit(1);
}

// Now sync with the CI endpoint
const http = require('http');

const postData = JSON.stringify(envContent);

const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/ci-secret-sync',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

const req = http.request(options, (res) => {
  let data = '';

  res.on('data', (chunk) => {
    data += chunk;
  });

  res.on('end', () => {
    console.log('Response status:', res.statusCode);
    console.log('Response body:', data);
  });
});

req.on('error', (e) => {
  console.error('Request error:', e.message);
  console.error('This is expected if the CI service is not running locally.');
  console.error('The secrets would be synced when the PR is opened.');
});

req.write(postData);
req.end();
EOF

