  app.get('/healthz', (req, res) => {
    try {
      // Validate database configuration
      if (!DATABASE_URL || !DATABASE_URL.startsWith('postgres://')) {
        console.error('Database connection not properly configured');
        res.status(503).json({ db: "error" });
        return;
      }

      // Parse database URL to simulate connection attempt
      try {
        const url = new URL(DATABASE_URL.replace('postgres://', 'http://'));

        // Basic validation: check if essential parts of the URL are present
        if (!url.hostname || !url.username) {
          console.error('Invalid database URL format');
          res.status(503).json({ db: "error" });
          return;
